expected = {"juniper":"pending","kelp":"verified","larch":"conflict","maple":"diverged"}
counter = {"events": instance[:2], "at":20, "expected":{"juniper":"pending"}}
payload = json.dumps({"source":source,"result":expected,"counterexample":counter})
decoded = json.loads(payload)
ns = {}
exec(decoded['source'], ns)
audit = ns['audit']
before = json.dumps(instance)
assert audit(instance,20) == decoded['result']
c = decoded['counterexample']
assert audit(c['events'],c['at']) == c['expected']
